// pages/Feed.jsx
import ReviewCard from "../components/ReviewCard";

function Feed() {
  return (
    <div style={{ padding: "20px" }}>
      <h1>📝 리뷰 피드</h1>
      <p>여기에 서버에서 가져온 리뷰 목록 출력합니다.</p>

      {/* ReviewCard는 재사용 컴포넌트 */}
      <ReviewCard
        username="연지"
        text="이 립밤 너무 좋아요!"
      />

      <ReviewCard
        username="유저123"
        text="이거 사지 마세요... 피부 뒤집혔어요"
      />
    </div>
  );
}

export default Feed;
